CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text UNIQUE NOT NULL, currency char(3) NOT NULL DEFAULT 'BRL', timezone text NOT NULL DEFAULT 'America/Sao_Paulo', locale text NOT NULL DEFAULT 'pt-BR', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name text NOT NULL, email text NOT NULL, password_hash text NOT NULL, role text NOT NULL DEFAULT 'manager' CHECK(role IN ('owner','admin','manager','frontdesk','housekeeping','finance','viewer')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,email));
CREATE TABLE IF NOT EXISTS properties(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name text NOT NULL, slug text NOT NULL, address jsonb NOT NULL DEFAULT '{}', check_in time NOT NULL DEFAULT '14:00', check_out time NOT NULL DEFAULT '12:00', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,slug));
CREATE TABLE IF NOT EXISTS room_types(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid NOT NULL REFERENCES properties(id) ON DELETE CASCADE, name text NOT NULL, description text NOT NULL DEFAULT '', capacity int NOT NULL DEFAULT 2, base_rate numeric(12,2) NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS rooms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid NOT NULL REFERENCES properties(id) ON DELETE CASCADE, room_type_id uuid NOT NULL REFERENCES room_types(id), number text NOT NULL, floor text NOT NULL DEFAULT '1', status text NOT NULL DEFAULT 'available' CHECK(status IN ('available','occupied','cleaning','maintenance','blocked')), active boolean NOT NULL DEFAULT true, UNIQUE(property_id,number));
CREATE TABLE IF NOT EXISTS guests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, full_name text NOT NULL, email text, phone text, country_code text, document_last4 text, notes text NOT NULL DEFAULT '', marketing_opt_in boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reservations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, property_id uuid NOT NULL REFERENCES properties(id) ON DELETE CASCADE, guest_id uuid NOT NULL REFERENCES guests(id), confirmation_code text UNIQUE NOT NULL, check_in date NOT NULL, check_out date NOT NULL, adults int NOT NULL DEFAULT 1, children int NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'confirmed' CHECK(status IN ('hold','confirmed','checked_in','checked_out','cancelled','no_show')), channel text NOT NULL DEFAULT 'direct', currency char(3) NOT NULL DEFAULT 'BRL', subtotal numeric(12,2) NOT NULL DEFAULT 0, tax numeric(12,2) NOT NULL DEFAULT 0, total numeric(12,2) NOT NULL DEFAULT 0, notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), CHECK(check_out>check_in));
CREATE TABLE IF NOT EXISTS reservation_rooms(reservation_id uuid PRIMARY KEY REFERENCES reservations(id) ON DELETE CASCADE, room_id uuid NOT NULL REFERENCES rooms(id), rate numeric(12,2) NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, reservation_id uuid REFERENCES reservations(id) ON DELETE SET NULL, amount numeric(12,2) NOT NULL, currency char(3) NOT NULL DEFAULT 'BRL', method text NOT NULL DEFAULT 'pix', status text NOT NULL DEFAULT 'paid', provider text, external_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS housekeeping_tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid NOT NULL REFERENCES properties(id) ON DELETE CASCADE, room_id uuid REFERENCES rooms(id) ON DELETE SET NULL, type text NOT NULL DEFAULT 'cleaning', priority text NOT NULL DEFAULT 'normal', status text NOT NULL DEFAULT 'pending', assigned_to uuid REFERENCES users(id) ON DELETE SET NULL, notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE IF NOT EXISTS ledger_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, property_id uuid REFERENCES properties(id) ON DELETE SET NULL, reservation_id uuid REFERENCES reservations(id) ON DELETE SET NULL, kind text NOT NULL CHECK(kind IN ('income','expense')), category text NOT NULL, description text NOT NULL, amount numeric(12,2) NOT NULL, currency char(3) NOT NULL DEFAULT 'BRL', occurred_on date NOT NULL DEFAULT current_date, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log(id bigserial PRIMARY KEY, organization_id uuid REFERENCES organizations(id) ON DELETE CASCADE, user_id uuid REFERENCES users(id) ON DELETE SET NULL, action text NOT NULL, entity text, entity_id text, metadata jsonb NOT NULL DEFAULT '{}', ip inet, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS reservations_dates_idx ON reservations(property_id,check_in,check_out,status);
CREATE INDEX IF NOT EXISTS guests_org_idx ON guests(organization_id,full_name);
CREATE INDEX IF NOT EXISTS ledger_org_date_idx ON ledger_entries(organization_id,occurred_on);
